/**
 * Vendored from AgentWorkforce/relay-chief (`src/contracts.ts`, `src/worker-protocol.ts`).
 * relay-chief is unpublished, so it cannot be a dependency here. Keep this file in step
 * with it: `src/protocol.test.ts` checks digests and reports against a fixture
 * generated by relay-chief's own code.
 */
import { createHash } from 'node:crypto';
import { z } from 'zod';

const ID = z.string().trim().min(1).max(200);
const COUNT = z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER);
const REPOSITORY = z
  .string()
  .regex(/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/)
  .transform((s) => s.toLowerCase());

export const ACTION_SCHEMA = z.enum(['investigate', 'coordinate', 'unblock']);
export type Action = z.infer<typeof ACTION_SCHEMA>;

const EVIDENCE_SCHEMA = z.strictObject({
  sourceId: ID,
  sessionId: ID,
  version: ID,
  organizationId: ID,
  workspaceId: ID,
  projectId: ID,
  repository: REPOSITORY,
  workKey: ID,
  resourceKeys: z.array(ID).min(1).max(100),
  observedAt: COUNT,
  summary: z.string().min(1).max(16_000),
  references: z.array(z.string().url().max(2000)).max(20),
});

const DIGEST = z.string().regex(/^[a-f0-9]{64}$/);

const ASSIGNMENT_SCHEMA = z.strictObject({
  protocol: z.literal('relay-chief.assignment.v1'),
  taskId: z.string().min(1).max(200),
  chiefId: z.string().min(1),
  organizationId: z.string().min(1),
  workspaceId: z.string().min(1),
  projectId: z.string().min(1),
  repository: z.string().min(1),
  workKey: z.string().min(1),
  resourceKeys: z.array(z.string().min(1)).min(1).max(100),
  action: ACTION_SCHEMA,
  worker: z.strictObject({
    agentId: z.string().min(1),
    address: z.string().min(1),
    actions: z.array(ACTION_SCHEMA).min(1),
  }),
  policyVersion: z.string().min(1),
  configurationRevision: z.number().int().positive(),
  policyDigest: DIGEST,
  reservationMicros: z.number().int().positive().max(Number.MAX_SAFE_INTEGER),
  evidenceDigest: DIGEST,
  evidence: EVIDENCE_SCHEMA,
  acceptance: z.array(z.string().min(1).max(2000)).min(1).max(20),
});
export type Assignment = z.infer<typeof ASSIGNMENT_SCHEMA>;

export type ReportState = 'accepted' | 'running' | 'completed' | 'failed';

export interface WorkerReport {
  protocol: 'relay-chief.report.v1';
  taskId: string;
  assignmentDigest: string;
  sequence: number;
  state: ReportState;
  artifactRefs: string[];
}

/**
 * Serializes a value with sorted keys, leaving out undefined fields.
 * @param value The value to serialize.
 * @returns The canonical JSON text every digest is computed over.
 */
export function canonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  if (value !== null && typeof value === 'object') {
    return `{${Object.entries(value)
      .filter(([, v]) => v !== undefined)
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
      .map(([k, v]) => `${JSON.stringify(k)}:${canonical(v)}`)
      .join(',')}}`;
  }
  return JSON.stringify(value) ?? 'null';
}

/**
 * @param value The value to digest.
 * @returns The SHA-256 hex digest of its canonical form.
 */
export function hash(value: unknown): string {
  return createHash('sha256').update(canonical(value)).digest('hex');
}

/**
 * Identity for this delivery, never from the message body. Agents come from Relay. The
 * workspace is Control's, from configuration, once the token's Relay workspace has matched.
 */
export interface AuthenticatedDelivery {
  workspaceId: string;
  senderAgentId: string;
  recipientAgentId: string;
  recipientAddress: string;
}

export interface AssignmentPolicy {
  chiefAgentId: string;
  chiefId: string;
  organizationId: string;
  projectId: string;
  repositories: string[];
  actions: Action[];
  maxReservationMicros: number;
  maxEvidenceAgeMs: number;
}

/**
 * Validates an assignment against authenticated delivery identity and this worker's policy.
 * Parsing lowercases repository names and trims evidence identifiers before the digest check.
 * @param delivery Identity read from Relay for this delivery.
 * @param raw The delivered message metadata.
 * @param policy What this worker accepts.
 * @param now The current time in milliseconds.
 * @returns The parsed assignment and its digest.
 * @throws `worker_assignment_invalid` or `worker_assignment_not_authorized`.
 */
export function readAssignment(
  delivery: AuthenticatedDelivery,
  raw: unknown,
  policy: AssignmentPolicy,
  now = Date.now()
): { assignment: Assignment; digest: string } {
  const parsed = z.object({ chief_assignment: ASSIGNMENT_SCHEMA, assignment_digest: DIGEST }).safeParse(raw);
  if (!parsed.success) throw new Error('worker_assignment_invalid');
  const assignment = parsed.data.chief_assignment;
  const assignmentDigest = parsed.data.assignment_digest;
  if (
    hash(assignment) !== assignmentDigest ||
    hash(assignment.evidence) !== assignment.evidenceDigest ||
    delivery.workspaceId !== assignment.workspaceId ||
    delivery.senderAgentId !== policy.chiefAgentId ||
    delivery.recipientAgentId !== assignment.worker.agentId ||
    delivery.recipientAddress !== assignment.worker.address ||
    assignment.chiefId !== policy.chiefId ||
    assignment.organizationId !== policy.organizationId ||
    assignment.projectId !== policy.projectId ||
    !policy.repositories.includes(assignment.repository) ||
    !policy.actions.includes(assignment.action) ||
    // Stricter than relay-chief, which only offers an action to a worker that declares it.
    !assignment.worker.actions.includes(assignment.action) ||
    assignment.reservationMicros > policy.maxReservationMicros ||
    assignment.evidence.observedAt > now ||
    now - assignment.evidence.observedAt > policy.maxEvidenceAgeMs ||
    assignment.evidence.organizationId !== assignment.organizationId ||
    assignment.evidence.workspaceId !== assignment.workspaceId ||
    assignment.evidence.projectId !== assignment.projectId ||
    assignment.evidence.repository !== assignment.repository ||
    assignment.evidence.workKey !== assignment.workKey ||
    hash([...new Set(assignment.evidence.resourceKeys)].sort()) !== hash(assignment.resourceKeys)
  ) {
    throw new Error('worker_assignment_not_authorized');
  }
  return { assignment, digest: assignmentDigest };
}
